<?php
/** Native WordPress primary-menu storage; no duplicated menu/options engine. */
namespace Marquesano\Admin\Panel;
defined('ABSPATH') || exit;
final class Navigation {
 public static function menu_id(){ $locations=get_nav_menu_locations();return absint($locations['primary']??0); }
 public static function items(){ $id=self::menu_id();return $id ? (wp_get_nav_menu_items($id,array('post_status'=>'publish'))?:array()) : array(); }
 public static function signature(){return hash('sha256',wp_json_encode(array_map(static function($i){return array($i->ID,$i->title,$i->url,$i->menu_order,$i->menu_item_parent,get_post_meta($i->ID,'_po_nav_hidden',true),get_post_meta($i->ID,'_po_nav_kind',true));},self::items())));}
 public static function kind($i){return get_post_meta($i->ID,'_po_nav_kind',true)?:('post_type'===$i->type && 'page'===$i->object?'page':'custom');}
 public static function defaults(){
  $rows=array();foreach(array('home'=>'Início','shop'=>'Produtos','categories'=>'Categorias','about'=>'Quem Somos','contact'=>'Contato') as $kind=>$label){$page=null;if('about'===$kind){foreach(array('quem-somos','sobre-nos','sobre') as $slug){$page=get_page_by_path($slug);if($page && 'publish'===$page->post_status){break;}$page=null;}}if('contact'===$kind){$page=get_page_by_path('contato');} $pid=$page && 'publish'===$page->post_status && !$page->post_password ? $page->ID : 0;
   $rows[]=array('id'=>0,'label'=>$label,'kind'=>in_array($kind,array('about','contact'),true)?'page':$kind,'page'=>$pid,'url'=>'','order'=>(count($rows)+1)*10,'visible'=>!in_array($kind,array('about','contact'),true)||$pid);
  }return $rows;
 }
 public static function rows(){ $items=self::items();if(!$items){return self::defaults();}$rows=array();$group=false;foreach($items as $i){if('taxonomy'===$i->type && 'product_cat'===$i->object){continue;}$kind=self::kind($i);$group=$group||'categories'===$kind;$rows[]=array('id'=>$i->ID,'label'=>$i->title,'kind'=>$kind,'page'=>'page'===$kind?(metadata_exists('post',$i->ID,'_po_nav_page_id')?absint(get_post_meta($i->ID,'_po_nav_page_id',true)):('page'===$i->object?(int)$i->object_id:0)):0,'url'=>'custom'===$kind?$i->url:'','order'=>$i->menu_order,'visible'=>!get_post_meta($i->ID,'_po_nav_hidden',true));}if(!$group){$rows[]=array('id'=>0,'label'=>'Categorias','kind'=>'categories','page'=>0,'url'=>'','order'=>30,'visible'=>true);}return $rows; }
 public static function selected(){ $items=self::items();$ids=array();foreach($items as $i){if('taxonomy'===$i->type && 'product_cat'===$i->object && !get_post_meta($i->ID,'_po_nav_hidden',true)){$ids[]=(int)$i->object_id;}}if(!$items){$ids=get_terms(array('taxonomy'=>'product_cat','hide_empty'=>true,'parent'=>0,'fields'=>'ids'));}return is_wp_error($ids)?array():array_map('intval',$ids); }
 public static function safe_url($raw){$raw=trim((string)$raw);if(preg_match('~^/(?!/)~',$raw)){$raw=home_url($raw);}$url=esc_url_raw($raw,array('http','https','mailto','tel'));if(!$url || !preg_match('~^(https?://|mailto:|tel:)~i',$url)){return ''; }if(preg_match('~^https?://~i',$url) && !wp_parse_url($url,PHP_URL_HOST)){return '';}return $url;}
 public static function category_nodes($terms,$selected,$orders=array()){
  $map=array();$selected=array_fill_keys(array_map('intval',$selected),true);foreach($terms as $t){if(!isset($selected[$t->term_id])){continue;}$url=get_term_link($t);if(is_wp_error($url)){continue;}$map[$t->term_id]=array('id'=>(int)$t->term_id,'parent'=>(int)$t->parent,'label'=>$t->name,'url'=>$url,'kind'=>'category','order'=>(int)($orders[$t->term_id]??0),'children'=>array());}
  foreach($map as &$n){if(!isset($map[$n['parent']])){$n['parent']=0;}}unset($n);
  $build=static function($parent,$depth=0) use (&$build,$map){if($depth>20){return array();}$out=array();foreach($map as $node){if($node['parent']===$parent){$node['children']=$build($node['id'],$depth+1);$out[]=$node;}}usort($out,static function($a,$b){return $a['order']<=>$b['order']?:strnatcasecmp($a['label'],$b['label']);});return $out;};return $build(0);
 }
 public static function tree(){
  $items=self::items();$terms=get_terms(array('taxonomy'=>'product_cat','hide_empty'=>false));$orders=array();foreach($items as $i){if('product_cat'===$i->object){$orders[$i->object_id]=$i->menu_order;}}
  $categories=self::category_nodes(is_wp_error($terms)?array():$terms,self::selected(),$orders);$nodes=array();foreach(self::rows() as $r){if(!$r['visible']){continue;}$url='';$children=array();switch($r['kind']){case 'home':$url=home_url('/');break;case 'shop':$url=function_exists('wc_get_page_permalink')?wc_get_page_permalink('shop'):'';break;case 'categories':$children=$categories;$url=function_exists('wc_get_page_permalink')?wc_get_page_permalink('shop'):'';if(!$children){continue 2;}break;case 'page':$p=get_post($r['page']);if($p && 'page'===$p->post_type && 'publish'===$p->post_status && !$p->post_password){$url=get_permalink($p);}break;default:$url=self::safe_url($r['url']);}
   if($url){$nodes[]=array('label'=>$r['label'],'url'=>$url,'kind'=>$r['kind'],'order'=>$r['order'],'children'=>$children);}}
  usort($nodes,static function($a,$b){return $a['order']<=>$b['order'];});return $nodes;
 }
 public static function save($data){
  need('manage_appearance');if('1'!==value($data,'navigation_complete') || !hash_equals(self::signature(),value($data,'version')) || self::menu_id()!==number($data,'menu_id')){throw new \RuntimeException('O menu mudou ou o formulário foi enviado incompleto. Recarregue antes de salvar.',409);}
  $rows=$data['items']??array();$selected=$data['cat_ids']??array();$orders=$data['cat_order']??array();if(!is_array($rows)||count($rows)>60||!is_array($selected)||count($selected)>1000||!is_array($orders)){throw new \RuntimeException('Seleção de navegação inválida.');}
  $existing=array();foreach(self::items() as $item){$existing[$item->ID]=$item;}$plan=array();$seen=array();$groups=0;
  foreach($rows as $row){if(!is_array($row)){throw new \RuntimeException('Item inválido.');}$id=number($row,'id');$kind=text($row,'kind');$label=text($row,'label');$pid=number($row,'page');$raw=value($row,'url');$visible=!empty($row['visible']);
   if(!$id&&!$label&&!$raw&&!$pid){continue;}if($id&&(!isset($existing[$id])||isset($seen[$id])||'product_cat'===$existing[$id]->object)){throw new \RuntimeException('Item não pertence ao menu atual.',403);}$seen[$id]=true;
   if(!in_array($kind,array('home','shop','categories','page','custom'),true)||!$label||strlen($label)>240){throw new \RuntimeException('Confira o tipo e o título do item.');}if('categories'===$kind && ++$groups>1){throw new \RuntimeException('Use apenas um grupo Categorias.');}
   $url='';if('custom'===$kind){$url=self::safe_url($raw);if(!$url){throw new \RuntimeException('Use um link HTTP, HTTPS, telefone ou e-mail válido.');}}
   if('page'===$kind){$p=$pid?get_post($pid):null;if($pid && (!$p||'page'!==$p->post_type||'publish'!==$p->post_status||$p->post_password)){throw new \RuntimeException('Selecione uma página publicada e pública.');}if(!$pid){$visible=false;}}
   $plan[]=array('id'=>$id,'kind'=>$kind,'label'=>$label,'page'=>$pid,'url'=>$url,'visible'=>$visible,'order'=>max(1,number($row,'order')));
  }
  foreach($existing as $id=>$i){if('product_cat'!==$i->object&&!isset($seen[$id])){throw new \RuntimeException('Itens do menu foram omitidos. Recarregue para preservar os links atuais.',409);}}
  $selected=array_values(array_unique(array_map('absint',array_filter($selected,'is_scalar'))));foreach($selected as $id){if(!get_term($id,'product_cat')||is_wp_error(get_term($id,'product_cat'))){throw new \RuntimeException('Categoria inexistente.');}}
  if($selected&&!$groups){throw new \RuntimeException('Mantenha o grupo Categorias para organizar a seleção.');}
  usort($plan,static function($a,$b){return $a['order']<=>$b['order'];});$menu=self::menu_id();if(!$menu){$menu=wp_create_nav_menu('Navegação principal Paraguai Online');if(is_wp_error($menu)){throw new \RuntimeException($menu->get_error_message());}$locations=get_nav_menu_locations();$locations['primary']=$menu;set_theme_mod('nav_menu_locations',$locations);}
  $group=0;foreach($plan as $r){$args=array('menu-item-title'=>$r['label'],'menu-item-status'=>'publish','menu-item-position'=>$r['order'],'menu-item-parent-id'=>0,'menu-item-type'=>'custom','menu-item-url'=>in_array($r['kind'],array('shop','categories'),true)?wc_get_page_permalink('shop'):($r['url']?:home_url('/')));
   if('page'===$r['kind']&&$r['page']){$args['menu-item-type']='post_type';$args['menu-item-object']='page';$args['menu-item-object-id']=$r['page'];}
   $id=wp_update_nav_menu_item($menu,$r['id'],$args);if(is_wp_error($id)){throw new \RuntimeException($id->get_error_message());}update_post_meta($id,'_po_nav_kind',$r['kind']);update_post_meta($id,'_po_nav_page_id',$r['page']);update_post_meta($id,'_po_nav_hidden',$r['visible']?0:1);if('categories'===$r['kind']){$group=$id;}
  }
  $term_items=array();foreach($existing as $i){if('product_cat'===$i->object){$term_items[(int)$i->object_id]=$i->ID;update_post_meta($i->ID,'_po_nav_hidden',1);}}
  foreach($selected as $term_id){$id=wp_update_nav_menu_item($menu,$term_items[$term_id]??0,array('menu-item-object-id'=>$term_id,'menu-item-object'=>'product_cat','menu-item-type'=>'taxonomy','menu-item-status'=>'publish','menu-item-position'=>max(1,absint($orders[$term_id]??100)),'menu-item-parent-id'=>$group));if(is_wp_error($id)){throw new \RuntimeException($id->get_error_message());}$term_items[$term_id]=$id;update_post_meta($id,'_po_nav_hidden',0);}
  foreach($selected as $term_id){$t=get_term($term_id,'product_cat');$parent=in_array((int)$t->parent,$selected,true)?$term_items[$t->parent]:$group;update_post_meta($term_items[$term_id],'_menu_item_menu_item_parent',(int)$parent);}
 }
}
function screen_navigation(){
 need('manage_appearance');$pages=get_posts(array('post_type'=>'page','post_status'=>'publish','has_password'=>false,'numberposts'=>1000,'orderby'=>'title','order'=>'ASC'));$choices=array(0=>'Selecionar página publicada');foreach($pages as $p){$choices[$p->ID]=$p->post_title;}$rows=Navigation::rows();$rows[]=array('id'=>0,'label'=>'','kind'=>'custom','page'=>0,'url'=>'','order'=>100,'visible'=>false);
 echo '<div class="mp-heading"><h1>Navegação do cabeçalho</h1></div><p>Reutiliza o menu nativo da posição principal. Menor número aparece primeiro. Desmarque Exibir para ocultar sem apagar. Páginas sem publicação ficam ocultas. Políticas podem permanecer no rodapé.</p>';form_start('navigation_save');echo '<input type="hidden" name="menu_id" value="'.Navigation::menu_id().'"><input type="hidden" name="version" value="'.esc_attr(Navigation::signature()).'">';
 foreach($rows as $i=>$r){$prefix='items['.$i.']';echo '<details class="mp-card" open><summary>Item '.($i+1).'</summary><input type="hidden" name="'.esc_attr($prefix.'[id]').'" value="'.(int)$r['id'].'"><div class="mp-form-grid">';input($prefix.'[label]','Título',$r['label']);select($prefix.'[kind]','Tipo',array('home'=>'Início','shop'=>'Produtos','categories'=>'Categorias (dropdown)','page'=>'Página publicada','custom'=>'Link personalizado'),$r['kind']);select($prefix.'[page]','Página institucional',$choices,$r['page']);input($prefix.'[url]','URL para link personalizado',$r['url']);input($prefix.'[order]','Ordem',$r['order'],'number','min="0" max="9999"');echo '<label class="mp-check"><input type="checkbox" name="'.esc_attr($prefix.'[visible]').'" value="1" '.checked($r['visible'],true,false).'>Exibir item</label></div></details>';}
 echo '<section class="mp-card"><h2>Categorias do dropdown</h2><p>Marque pais e filhas que deseja mostrar. Uma filha sem o pai selecionado aparece na raiz. As categorias não são criadas nem modificadas aqui.</p><div style="max-height:420px;overflow:auto">';$terms=get_terms(array('taxonomy'=>'product_cat','hide_empty'=>false));$selected=Navigation::selected();$orders=array();foreach(Navigation::items() as $item){if('product_cat'===$item->object){$orders[$item->object_id]=$item->menu_order;}}
 foreach(is_wp_error($terms)?array():$terms as $term){echo '<div class="mp-inline" style="margin-bottom:10px;padding-left:'.min(120,count(get_ancestors($term->term_id,'product_cat'))*16).'px"><label class="mp-check"><input type="checkbox" name="cat_ids[]" value="'.(int)$term->term_id.'" '.checked(in_array((int)$term->term_id,$selected,true),true,false).'>'.esc_html($term->name).'</label><label>Ordem <input type="number" min="0" max="9999" name="cat_order['.(int)$term->term_id.']" value="'.(int)($orders[$term->term_id]??100).'" style="width:80px"></label></div>';}
 echo '</div></section><input type="hidden" name="navigation_complete" value="1"><button type="submit">Salvar navegação</button></form>';
}